package com.nicole.nudge;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;
public class NudgeAlarmReceiver extends BroadcastReceiver {
 static PendingIntent alarmIntent(Context context,JSONObject task){Intent i=new Intent(context,NudgeAlarmReceiver.class).setAction("fire").putExtra("id",task.optString("id")).putExtra("title",task.optString("title"));return PendingIntent.getBroadcast(context,task.optString("id").hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void scheduleOne(Context context,JSONObject task){long when=task.optLong("next");if(context.getSharedPreferences("nudge",0).getLong("fired-"+task.optString("id"),-1)==when)return;if(when<=System.currentTimeMillis())when=System.currentTimeMillis()+5000;AlarmManager alarm=(AlarmManager)context.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=alarmIntent(context,task);if(Build.VERSION.SDK_INT<31||alarm.canScheduleExactAlarms())alarm.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else alarm.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}
 static void scheduleAll(Context context,JSONObject data)throws Exception{SharedPreferences p=context.getSharedPreferences("nudge",0);JSONObject old=new JSONObject(p.getString("reminders","{\"tasks\":[]}"));AlarmManager alarms=(AlarmManager)context.getSystemService(Context.ALARM_SERVICE);JSONArray before=old.optJSONArray("tasks");if(before!=null)for(int i=0;i<before.length();i++)alarms.cancel(alarmIntent(context,before.getJSONObject(i)));p.edit().putString("reminders",data.toString()).apply();JSONArray tasks=data.optJSONArray("tasks");if(tasks!=null)for(int i=0;i<tasks.length();i++)scheduleOne(context,tasks.getJSONObject(i));}
 @Override public void onReceive(Context context,Intent intent){String id=intent.getStringExtra("id"),action=intent.getAction();if(id==null)return;NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);SharedPreferences prefs=context.getSharedPreferences("nudge",0);try{JSONObject state=new JSONObject(prefs.getString("reminders","{\"tasks\":[]}"));JSONArray tasks=state.optJSONArray("tasks");JSONObject task=null;int index=-1;for(int i=0;tasks!=null&&i<tasks.length();i++)if(id.equals(tasks.getJSONObject(i).optString("id"))){task=tasks.getJSONObject(i);index=i;break;}if(task==null)return;
 if("done".equals(action)||"snooze".equals(action)){JSONArray actions=new JSONArray(prefs.getString("actions","[]"));JSONObject update=new JSONObject().put("id",id).put("type",action);if("done".equals(action))tasks.remove(index);else{long now=System.currentTimeMillis(),next=now+18L*3600000L;Calendar cal=Calendar.getInstance();cal.setTimeInMillis(next);JSONObject settings=state.optJSONObject("settings");String[] start=(settings==null?"09:00":settings.optString("start","09:00")).split(":"),end=(settings==null?"20:00":settings.optString("end","20:00")).split(":");int minutes=cal.get(Calendar.HOUR_OF_DAY)*60+cal.get(Calendar.MINUTE),first=Integer.parseInt(start[0])*60+Integer.parseInt(start[1]),last=Integer.parseInt(end[0])*60+Integer.parseInt(end[1]);if(minutes>=last)cal.add(Calendar.DAY_OF_MONTH,1);if(minutes<first||minutes>=last){cal.set(Calendar.HOUR_OF_DAY,Integer.parseInt(start[0]));cal.set(Calendar.MINUTE,Integer.parseInt(start[1]));cal.set(Calendar.SECOND,0);}next=cal.getTimeInMillis();long deadline=task.optLong("deadline",0);if(deadline>now)next=Math.min(next,now+Math.max(1000,(deadline-now)/2));task.put("next",next);update.put("next",next);scheduleOne(context,task);}actions.put(update);prefs.edit().putString("actions",actions.toString()).putString("reminders",state.toString()).apply();manager.cancel(id.hashCode());return;}
 prefs.edit().putLong("fired-"+id,task.optLong("next")).apply();manager.createNotificationChannel(new NotificationChannel("nudges","Gentle nudges",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(context,id.hashCode(),new Intent(context,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent done=new Intent(context,NudgeAlarmReceiver.class).setAction("done").putExtra("id",id),snooze=new Intent(context,NudgeAlarmReceiver.class).setAction("snooze").putExtra("id",id);Notification notification=new Notification.Builder(context,"nudges").setSmallIcon(R.drawable.ic_nudge).setContentTitle("A little nudge").setContentText(task.optString("title")).setStyle(new Notification.BigTextStyle().bigText(task.optString("title"))).setContentIntent(open).setAutoCancel(true).addAction(new Notification.Action.Builder(null,"Done",PendingIntent.getBroadcast(context,(id+"done").hashCode(),done,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build()).addAction(new Notification.Action.Builder(null,"Remind me again",PendingIntent.getBroadcast(context,(id+"snooze").hashCode(),snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build()).build();manager.notify(id.hashCode(),notification);
 }catch(Exception ignored){}}
}
